&quot; in prompt else prompt return body[:60 if &quot;两句话&quot; in prompt else 90] # 截原文当摘要，数字必有依据 return json.dumps({&quot;faithfulness&quot;: 3 + h % 3, # mock：rubric 打分 &quot;coverage&quot;: 2 + h % 4, &quot;conciseness&quot;: 2 + h % 4, &quot;reason&quot;: &quot;mock 打分&quot;}) from openai import OpenAI client = OpenAI(base_url=os.environ.get(&quot;AGENT_LLM_BASE_URL&quot;, &quot;https://api.openai.com/v1&quot;), api_key=os.environ[&quot;AGENT_LLM_API_KEY&quot;]) model = os.environ.get(&quot;AGENT_LLM_MODEL&quot;, &quot;gpt-4o-mini&quot;) messages = ([{&quot;role&quot;: &quot;system&quot;, &quot;content&quot;: system}] if system else []) + [{&quot;role&quot;: &quot;user&quot;, &quot;content&quot;: prompt}] return client.chat.completions.create(model=model, messages=messages, temperature=temperature).choices[0].message.content or &quot;&quot; ▸ 代码怎么读：llm() 是全书统一的模型接入约定——只读三个环境变量，任何 OpenAI 兼容网关即插即用。关键设计是无密钥时的确定性 mock：用 hash(prompt) 而非随机数，同一请求永远返回同一答案，评估流程可以先离线跑通再接真实模型。mock 按请求特征分流（成对比较/摘要生成/rubric 打分），因为评估器对三种调用解析不同的 JSON 形状；读者接自己的业务时，删掉 mock 分支、保留 try/except 即可。 片段 2/4：程序断言（塔基）与 rubric 定义 def strip_fence(raw: str) -&gt; str: &quot;&quot;&quot;剥掉模型可能自行添加的代码围栏，保证 JSON 可解析。&quot;&quot;&quot; text = raw.strip() if text.startswith(FENCE): text = text.split(&quot;
&quot;, 1)[1] if &quot;
&quot; in text else &quot;&quot; return text[:-len(FENCE)].strip() if text.endswith(FENCE) else text @dataclass class Rubric: &quot;&quot;&quot;评分规则：每个维度一条可核对的判据，裁判须逐条引用判据后给分。&quot;&quot;&quot; dimensions: dict[str, str] = field(default_factory=lambda: { &quot;faithfulness&quot;: &quot;摘要中的每个论断是否都能在原文中找到依据（编造计 1 分）&quot;, &quot;coverage&quot;: &quot;原文关键信息点被覆盖的比例&quot;, &quot;conciseness&quot;: &quot;无重复无注水；长度不单独计分，冗余才扣分&quot;}) def programmatic_checks(text: str, source: str) -&gt; list[str]: &quot;&quot;&quot;塔基断言（免费、确定、先跑）：长度、占位符、数字真实性三类结构性失败。&quot;&quot;&quot; failures: list[str] = [] if not (20 &lt;= len(text) &lt;= 400): failures.append(f&quot;长度越界：{len(text)} 字&quot;) if re.search(r&quot;TODO|占位|省略&quot;, text): failures.append(&quot;含占位符&quot;) if ghost := set(re.findall(r&quot;\d+&quot;, text)) - set(re.findall(r&quot;\d+&quot;, source)): failures.append(f&quot;出现原文没有的数字（疑似编造）：{ghost}&quot;) return failures ▸ 代码怎么读：programmatic_checks 是评估金字塔的塔基——毫秒级、零成本、完全确定，所以放在裁判之前先跑，把结构性失败（长度越界、占位符、编造数字）直接判死，裁判预算只花在语义判断上。数字真实性检查（集合差）是摘要场景最便宜的忠实度近似：原文没有的数字几乎必然是编造。Rubric 把判据写成「可核对的陈述」而非形容词，是 19.5.2 消偏纪律的落点——裁判必须逐条引用判据才能给分。strip_fence 处理的是真实世界最常见的小故障：模型把 JSON 包在代码围栏里返回。 片段 3/4：rubric 打分（失效降级）与换序成对比较（消偏） class Judge: &quot;&quot;&quot;塔身评估器：rubric 绝对打分 + 换序成对比较，带失效降级与成本计数。&quot;&quot;&quot; def __init__(self, rubric: Rubric): self.rubric = rubric self.calls, self.fails = 0, 0 # 成本与失效计数（都应进监控） def score(self, text: str, source: str) -&gt; dict: &quot;&quot;&quot;rubric 打分（先理由后结论）；裁判失效降级到确定性启发式，链路不中断。&quot;&quot;&quot; rubric = &quot;
&quot;.join(f&quot;- {k}：{v}&quot; for k, v in self.rubric.dimensions.items()) system = (&quot;你是严格的评估裁判。逐维度核对判据后打 1-5 分，先给理由再给分。&quot; &quot;只输出 JSON：{\&quot;&lt;维度&gt;\&quot;: &lt;1-5&gt;, ..., \&quot;reason\&quot;: \&quot;一句话总评\&quot;}&quot;) prompt = f&quot;原文：
{source}

待评摘要：
{text}

评分规则：
{rubric}&quot; try: data = json.loads(strip_fence(llm(prompt, system, temperature=0.0))) self.calls += 1 dims = {k: int(data[k]) for k in self.rubric.dimensions} return {&quot;scores&quot;: dims, &quot;reason&quot;: str(data.get(&quot;reason&quot;, &quot;&quot;))} except Exception as exc: # 降级：长度比接近原文 1/3 给中评 self.fails += 1 fb = min(5, max(1, round(5 - abs(len(text) / max(len(source), 1) - 0.33) * 8))) return {&quot;scores&quot;: {k: fb for k in self.rubric.dimensions}, &quot;reason&quot;: f&quot;[裁判失效降级] {exc}&quot;} def pairwise(self, a: str, b: str, context: str) -&gt; dict: &quot;&quot;&quot;换序各判一次：两次一致才算胜，不一致记平局——位置偏差变不成方向性错误。&quot;&quot;&quot; system = (&quot;你是成对比较裁判。忽略位置与长度，判断哪个回答更好。&quot; &quot;只输出 JSON：{\&quot;winner\&quot;: \&quot;A|B|tie\&quot;, \&quot;reason\&quot;: \&quot;一句话理由\&quot;}&quot;) def one(prompt: str) -&gt; str: self.calls += 1 return str(json.loads(strip_fence(llm(prompt, system, temperature=0.0)))[&quot;winner&quot;]) base = f&quot;背景：{context}

回答A：
{a}

回答B：
{b}&quot; swap = base.replace(&quot;回答A&quot;, &quot;@T@&quot;).replace(&quot;回答B&quot;, &quot;回答A&quot;).replace(&quot;@T@&quot;, &quot;回答B&quot;) try: w1, w2 = one(base), {&quot;A&quot;: &quot;B&quot;, &quot;B&quot;: &quot;A&quot;, &quot;tie&quot;: &quot;tie&quot;}[one(swap)] except Exception as exc: # 解析失败/非法标签：降级为 unknown self.fails += 1 return {&quot;winner&quot;: &quot;unknown&quot;, &quot;reason&quot;: f&quot;裁判解析失败：{exc}&quot;} return ({&quot;winner&quot;: w1, &quot;reason&quot;: &quot;换序一致，判定可信&quot;} if w1 == w2 else {&quot;winner&quot;: &quot;tie&quot;, &quot;reason&quot;: &quot;换序不一致（位置偏差），记平局&quot;}) ▸ 代码怎么读：score() 的降级路径是本片段的灵魂——裁判输出缺维度、JSON 解析失败、网络抖动，任何一种都走 except 降级到确定性启发式（长度比接近原文 1/3 给中评）并计入 fails，评估流水线不因裁判抖动而整体中断，失效率进监控。pairwise() 的换序实现值得逐行看：swap 用占位符 @T@ 做两步替换，避免「回答A→回答B→回答A」的连环覆盖；w2 做标签还原映射，使两次判断可比。两次一致才算胜——这是把 MT-Bench 测得的 65% 换序自一致率变成工程约束：位置噪声最多把结论打成平局，变不成方向性错误。 片段 4/4：演示主程序 SOURCE = (&quot;公司季度报告：本季度营收 1200 万元，同比增长 18%。核心业务线用户数达 45 万。&quot; &quot;成本方面，云支出下降 9%，主要来自缓存优化。下季度计划扩展东南亚市场，&quot; &quot;预算 300 万元。风险提示：汇率波动可能影响海外收入。&quot;) PROMPT_V1 = &quot;请总结以下文本：
{src}&quot; PROMPT_V2 = &quot;请用不超过两句话总结以下文本的关键数字与计划，不要添加原文没有的信息：
{src}&quot; if __name__ == &quot;__main__&quot;: ev = Judge(Rubric()) cands: dict[str, str] = {} for name, tpl in [(&quot;v1&quot;, PROMPT_V1), (&quot;v2&quot;, PROMPT_V2)]: raw = llm(tpl.format(src=SOURCE), temperature=0.2) cands[name] = raw hard = programmatic_checks(raw, SOURCE) # 塔基先筛结构性失败 soft = ev.score(raw, SOURCE) # 塔身打语义分 print(f&quot;[{name}] 断言：{'通过' if not hard else hard}｜rubric：{soft['scores']}&quot;) verdict = ev.pairwise(cands[&quot;v1&quot;], cands[&quot;v2&quot;], context=&quot;公司季度报告摘要&quot;) print(f&quot;
成对比较（换序消偏）：胜者={verdict['winner']}（{verdict['reason']}）&quot;) print(f&quot;裁判调用 {ev.calls} 次，失效降级 {ev.fails} 次&quot;) ▸ 代码怎么读：演示串起完整评估流——同一原文、两个提示词版本 → 塔基断言（免费）→ 塔身 rubric 打分（带理由）→ 塔尖成对终审（换序消偏）。calls/fails 在结束时打印，是 19.6.3「评估体系自身可观测」的最小实现。真实使用时把 SOURCE/PROMPT 换成你的业务样例，把 v1/v2 换成待比较的两个版本；注意成对比较的成本是两次裁判调用，只对关键维度启用。 19.6.2 框架差异速览（LLM 观测与评估平台） 第二套完整框架程序不再给出——本章能力的平台化差异一张表说清： 平台 trace 形态 在线 eval 一句话差异 OpenTelemetry GenAI span + gen_ai.* 语义属性（规范） 无内置，需自建抽样判分 遥测底座：协议中立，汇入任意后端 Langfuse Trace→Observation 树，自带成本核算 Evaluation/Score 对象按抽样率挂 trace 开源全功能，可自托管 LangSmith Run 树（root/child runs） Feedback 与数据集评价 LangChain 官方一体化 SaaS 自建（本节实现） 最小 span 树 + 原样导出 抽样率挂在 tracer 上 十几行先跑通形状，再迁标准平台 19.6.3 生产化改造清单 错误处理：裁判输出解析失败必须降级（启发式或跳过）并计数，禁止让评估流水线因裁判抖动而整体失败；裁判失效率进监控。 超时与并发：黄金集回归用有界并发跑（如 8 路），单案例设超时；超时计入失败而非崩溃。 缓存：以"案例 ID + 被测版本 + 裁判版本"为键缓存裁判结论，重复回归不重复付费；被测版本变更才失效。 可观测：评估体系自身也要可观测——裁判调用数、成本、失效率、黄金集各层耗时做成看板，评估流水线挂了要有告警。 成本控制：抽样分层（塔基全量、裁判抽样）；成对比较换序只在关键维度启用；长文本先截断或分段再评。 数据卫生：黄金集进版本管理并设访问控制；金丝雀串检测泄漏；对执行 agent 保密参考答案；坏案例回流走人工标注闸门。 裁判治理：裁判与执行模型异源；定期人工标定一致率；rubric 变更走评审；对照样本常驻评估集做裁判体检。 门禁纪律：阈值绑定基线相对比较；例外合并强制留痕并告警；分数必须绑定"代码×数据集×裁判"三元组版本。 在线联动：metric 异常（成功率、p95、eval 均分）接告警与自动回滚；降级事件（第 12 章）打标进 trace，降级率超阈值同样告警。 19.7 概览 / 核心要点 / 结论 本章小结 评估与监控把智能体系统的质量从"感觉"变成"工程事实"：评估金字塔用三经济学分层（断言高频免费、回归发布前把关、A/B 终审真相），LLM-as-judge 补上语义判据但必须消位置偏差、控冗长偏差并定期人工标定，黄金集按分层、版本化、防污染、保鲜四原则管理，CI 门禁把分数变成发布流程的一等公民，在线 trace/metric/eval 三件套以分位值与切片盯住真实流量。评估不是开发完成后的附加题，而是与提示词、代码同等地位的系统构件——它决定了一个团队能不能安全地快速迭代。 核心要点 评估金字塔三层是三种经济学：塔基每次改动跑，塔身每次发布跑，塔尖低频高置信；缺任何一层都会让某类失败直通生产。 LLM-as-judge 适用前提是裁判显著强于选手；成对比较换序取平均消位置偏差，rubric 显式列"简洁性"消冗长偏差，裁判与执行模型异源消自我偏好。 绝对分数会漂移，成对相对判断不会；必须用绝对分时给锚定样例。 黄金集是体系的度量基准：分层（冒烟/回归/挑战）、版本化（代码×数据×裁判三元组）、防污染（答案保密、金丝雀串）、保鲜（坏案例单向回流）。 门禁用相对基线而非绝对阈值；非确定性输出要多次采样并计方差；门禁例外必须留痕，"为过门禁而放宽门禁"要告警。 延迟看 p50/p95/p99 而非均值，重尾分布下均值会说谎；metric 必须按任务类型切片，全局均值掩盖局部塌方。 trace 按 OTel GenAI 语义约定的形状存，保证可回放、可汇入标准观测后端；每条坏案例都要能凭 trace 复原。 Goodhart 陷阱是体系的终极敌人：定期轮换 rubric、混入对抗样本、以在线真实指标为最终裁决。 结论 一个智能体团队的迭代速度上限，不由模型能力决定，而由评估体系的置信度决定——敢不敢合并、敢不敢上线、敢不敢切模型，背后都是"我们的分数可信吗"。评估与监控模式的全部工程细节（消偏、防污染、分位值、门禁纪律）都在回答同一个问题：如何让度量在噪声、偏差与博弈权衡的围攻下依然指向真相。把这个体系搭好，第 9 章的学习与适应才有安全的燃料，前十八章的每一个模式才有被验证的机会。 19.8 延伸阅读与参考链接 论文 - MT-Bench / LLM-as-judge（裁判一致性与四类偏差的系统验证）：arXiv:2306.05685 - HELM（"整体评估"方法论，多维度剖面）：arXiv:2211.09110 - SWE-bench（真实 issue 基准与"改测试作弊"讨论）：arXiv:2310.06770 - GAIA（测试集答案私有化的抗污染设计）：arXiv:2311.12983 - τ-bench（工具调用对话评测与 pass^k 指标）：arXiv:2406.12045 - RAGAS（RAG 评估的可计算维度拆解）：arXiv:2309.15217 官方文档与规范 - OpenTelemetry GenAI 语义约定（gen_ai.* 属性族）：https://opentelemetry.io/docs/specs/semconv/gen-ai/ - Langfuse（开源 LLM 可观测与评估平台）文档：https://langfuse.com/docs - LangSmith（评估、数据集与监控）文档：https://docs.smith.langchain.com/ - SWE-bench 官网（含 Verified 排行榜）：https://www.swebench.com/ - LMArena（Chatbot Arena 现址，人类偏好排行榜）：https://lmarena.ai/ - RAGAS 官方文档：https://docs.ragas.io/ 案例来源 - Klarna AI 助手首月数据官方新闻稿（2024-02-27）：https://www.klarna.com/international/press/klarna-ai-assistant-handles-two-thirds-of-customer-service-chats-in-its-first-month/ - OpenAI 发布 SWE-bench Verified（2024-08-13）：https://openai.com/index/introducing-swe-bench-verified/

 一句话定义：让智能体在价值未知的空间里主动试错——生成假设、设计可证伪的实验、按探索-利用策略分配搜索预算、用自动验证器裁决结果，从而产出系统原先不知道的新答案、新策略或新知识。 解决什么问题：执行型智能体只在已知映射里工作，永远发现不了更好的解；而没有预算与验证约束的"探索"会退化为漫无目的的乱试，产出无法分辨真伪的噪声 ｜ 适用场景：参数与策略搜索、工具与路径发现、科学研究辅助（假设生成与实验设计）、深度调研、优化问题（算法/提示词/配置的自动改进）｜ 核心机制：假设生成 → 自动验证 → 选择保留 → 变异再生成（进化循环），配探索-利用预算管理与验证闸门 ｜ 代价：搜索消耗大量调用预算；绝大多数假设会被证伪；发现的真实性与新颖性需要比执行更强的验证投入。 本章速读 执行型智能体只会"做已知"，本章让系统"找未知"。怎么做：①LLM 当假设生成器提候选；②确定性自动验证器独立打分（生成与验证必须隔离）；③进化保留冠军与多样次优作母本，变异再生成；④留出集复验+异源对抗审稿+人类签核的闸门裁决"什么算发现"，配预算硬上限与无改进早停。何时别用：解空间可枚举、验证成本与真实实验无异、一次性任务。 21.1 模式概述 21.1.1 问题背景：为什么需要这个模式 全书前二十章的模式有一个共同前提：任务及其解法是给定的——规划模式把给定目标展开为步骤，反思模式把给定产出改得更好，路由模式把请求分给最合适的处理者。但有一类工作的本质不是执行已知，而是寻找未知：哪个检索策略对这个冷门语料最有效？哪个提示词变体能让工具调用错误率下降？某个开放问题的下界能不能再推一格？这类工作的失败方式与前二十章不同——执行型系统的失败是"做错了"，探索型系统的失败是"没有找到"（预算烧完一无所获）或"找到了假货"（把噪声、过拟合或巧合当成发现）。 LLM 给探索带来了一种新的可能性，也带来了一种新的危险。可能性是：模型可以作为假设生成器——它读过人类积累的巨量文本，能提出有根据的候选（"试一试按价值密度排序""这个数列像 cap set 的构造思路"），让搜索从盲目采样变成有先验引导的采样。危险是：模型同样是自信的编造者——它会一本正经地宣称某个假设"显然成立"，会为偶然通过的样本编造漂亮理由。因此本章的全部工程纪律都围绕一个判断展开：模型的职责是提出猜想，验证的职责必须交给独立的、最好可自动执行的判据。这正是科学方法的老原则——猜想与验证分离——在智能体工程里的再现。 21.1.2 核心机制：它如何工作 机制是一个最小发现循环，四个角色分工。假设生成器（通常是 LLM）：基于当前已知最优解与历史失败，提出新的候选解——可以是一段代码、一个参数配置、一条检索策略、一个科学假设。变异算子：对现有候选做局部修改（换排序键、调参数、改构造方式），LLM 的少量样本提示就是变异算子的自然形态——给它看最优解与几个次优解，让它提出改动。自动验证器：对每个候选给出客观分数——单元测试、基准评测、模拟环境、数学核验；验证器必须是确定性的、独立于生成器的、造价可控的。选择保留机制（进化数据库）：保留历史最优与有多样性的次优解，作为下一轮变异的母本；这就是进化搜索的"记忆"，也是搜索预算的账本。 循环之外有两层治理。搜索预算管理回答"探索到什么时候停"：总调用次数上限、无改进早停、探索-利用策略（随机尝试新假设 vs 围绕最优精修）。验证闸门回答"什么才算发现"：通过训练集的候选必须在留出集上复验（防过拟合），代码候选必须过语法与运行安全检查，声明式的"发现"必须附可复现的证据链。这四件组件恰好对应科学方法的三段论——猜想（生成器）、实验（验证器）、同行评审（闸门）——加上进化计算的选择机制。 flowchart LR GEN["假设生成器LLM 出候选"] --> VER["自动验证器训练集打分"] VER --> GATE{"验证闸门：留出集复验"} GATE -->|证伪| FAIL["失败记录（沉淀先验）"] GATE -->|通过| KB["知识入库：冠军+证据包"] KB --> POOL["母本池：冠军+多样次优"] FAIL --> POOL POOL -->|变异再生成| GEN BUD["预算管理：硬上限/无改进早停"] --> GEN 图 21-1：假设-实验-证伪-知识入库的发现环——生成与验证隔离，证伪记录与冠军共同构成下一轮的母本与先验。 21.1.3 与相邻模式的关系与组合 与学习与适应（第 9 章）是"探索产生训练信号"的供需关系：探索循环的每一次验证结果都是一条标注数据（这个策略值多少分），沉淀下来就是第 9 章优化提示词、更新 few-shot 库、微调的原料；反过来，学习到的先验又让下一轮探索的假设质量更高——探索与学习构成"越用越聪明"的外环。与优先级排序（第 20 章）共享多臂老虎机的数学基座：第 20 章用 UCB 思想分配任务预算，本章用它分配搜索预算——探索本身就是一种要排队的任务。与反思（第 4 章）的区别在对象：反思改进的是单次产出的质量（已知好坏标准），探索寻找的是未知的好坏标准下的新解；反思的判据是给定的，探索的核心难题恰是判据的可信。与评估与监控（第 19 章）是验证闸门的供应商：探索产出的每个"发现"都要过第 19 章的评估流程（留出集复验、防污染），否则就是自卖自夸。与并行化（第 3 章）是执行加速：多个假设可以并行验证，验证器天然是无依赖的批处理负载。 21.2 源起：它从哪里来 探索与发现有两股源头。理论线是「怎么分配尝试」：1933 年 Thompson 用后验采样形式化探索-利用权衡，1952 年 Robbins 把多臂老虎机变成可分析问题，2002 年 UCB1 证明对数 regret 界。方法论线：Popper 1934 年提出可证伪性，划定「什么配称为发现」。两线在 2023 年交汇：DeepMind 的 FunSearch 让 LLM 提候选、评估器打分、进化迭代，把 cap set n=8 最大构造从 496 点推到 512 点；AlphaEvolve（2025）推向矩阵乘法等开放问题。同期反面教材：The AI Scientist 的自动评审被注入操纵，印证本章铁律——验证一旦可被生成方操纵，探索就退化为自嗨。 年份月 事件 提出者/机构 出处 1933 Thompson Sampling：探索-利用的最早形式化 William R. Thompson Biometrika 1934 可证伪性：「什么算发现」的划界标准 Karl Popper 斯坦福哲学百科 2002 UCB1：探索预算的对数 regret 上界 Auer, Cesa-Bianchi, Fischer Machine Learning 47 2023-12 FunSearch：cap set n=8 下界 496→512（Nature 2024） Romera-Paredes 等（DeepMind） Nature 625, 468-475 2025-05 AlphaEvolve：4×4 复矩阵乘法 48 次乘法新算法 Balog 等（Google DeepMind） DeepMind 博客 21.3 发挥的作用：为什么重要 第一，它把系统的能力上限从"训练数据"扩展到"搜索空间"。执行型系统再精巧，最好成绩也不会超过其内置策略；带探索循环的系统可以持续刷新自己的最好成绩——FunSearch 与 AlphaEvolve 发现的不是"模型记得的答案"，而是搜索过程第一次产生的新构造。对企业系统，这对应着提示词、策略、配置的持续自动改进：探索循环每周跑一遍，最优解持续进化。 第二，它是学习与适应（第 9 章）的燃料来源。学习需要"哪个更好"的标注，而标注要么靠人（贵、慢），要么靠探索（自动产生带分数的对照数据）。没有探索机制的学习系统只能复述历史偏好；有探索机制的系统在不断制造自己的训练数据——这是"越用越好"与"越用越僵"的分水岭。 第三，它为开放域任务提供了诚实的产出标准。深度研究、科学辅助这类任务的难点不在生成而在担保：结论凭什么可信。探索-验证循环把"担保"工程化——每个结论背后是一条可复查的实验链（假设、判据、结果、复验），而不是一段流畅的论证。这让智能体的研究产出第一次可以被同行审计，也让 Deep Research 类产品敢于把"带引用"作为核心承诺。 21.4 实际应用与案例 提示词与策略的自动优化。场景：客服 agent 的系统提示词需要持续改进。做法：把提示词当作"基因组"，验证器是黄金集上的评估分数（第 19 章），LLM 每轮阅读当前最优提示词与失败案例后提出变体，进化保留最优；每版新冠军必须在留出集复验。关键设计点：变异幅度受限（一次只改一段），防止"推倒重来"式变异摧毁已积累的性能。 冷启动策略发现。场景：新上线的数据分析 agent 不知道哪类检索策略适合企业内部语料。做法：预置策略池（关键词、向量、混合、重排序）加几个新组合假设，在抽样任务集上自动评测各策略，UCB 式分配评测预算——前期雨露均沾，后期集中验证领先者。关键设计点：探索结果（策略排名及其置信区间）沉淀为第 9 章可学习的先验。 数学与算法发现。场景：团队需要优化一个热点函数的性能。做法：FunSearch 式配置——LLM 变异函数实现，验证器先跑正确性测试再测性能，进化数据库保留 Pareto 前沿；发现的新实现必须通过 fuzzing 与代码评审双闸门才能合入。关键设计点：正确性验证是硬门槛（一票否决），性能是优化目标——顺序不可颠倒。 深度调研 agent。场景：产出行业综述报告。做法：把"哪些子问题值得查"本身作为探索空间——第一轮广撒网获取信息增益信号（哪些查询带回新事实），后续轮次向高增益方向收敛；每条关键结论必须有两个独立来源交叉验证（可证伪性的信息版）。关键设计点：信息增益的估计天然倾向冷门来源，需配冗余惩罚防止猎奇跑偏。 科学实验辅助。场景：生物或材料实验室的假设排期。做法：Agent Laboratory 式分工——LLM 负责文献综述、假设清单与实验方案草案，验证器是预注册的统计检验方案，人类科学家保留假设取舍权；自动系统的产出定位为"待验证的建议"而非"结论"。关键设计点：预注册（先定判据后跑实验）是防 p-hacking 的闸门，与第 19 章的"先定判据后看结果"同构。 工具与接口发现。场景：接入新环境的 agent 不知道有哪些可用 API。做法：探索循环主动试调未文档化的端点（只读操作优先），把探测结果与 OpenAPI 规范（第 10 章 MCP）交叉验证后写入工具库。关键设计点：探索只允许在只读、沙箱化的操作上进行——写操作的探索权永远留给人类。 真实世界实例 OpenAI Deep Research：带引用的自动研究产品。2025 年 2 月 2 日，OpenAI 发布 Deep Research（基于为浏览与分析优化的 o3 版本）：给定问题后自主多步浏览网页、检索数百个来源并交叉整合，产出带清晰引用的报告，发布时在 Humanity's Last Exam 上取得 26.6% 准确率（远超当时的非推理基线）——"探索-综合-引用"从论文能力变成大众可用的产品形态。来源：OpenAI 官方发布。 Google AI co-scientist：假设生成与实验室验证的分工。2025 年 2 月，Google 发布基于 Gemini 2.0 的多智能体"AI 共同科学家"（generate-debate-evolve 架构），在药物重定位与靶点发现上产出经实验室验证的假设：急性髓系白血病的重定位候选药在临床可用浓度下显示体外抑瘤活性，肝纤维化的新表观遗传靶点在人体肝脏类器官实验中验证出抗纤维化活性（合作方含 Houston Methodist、斯坦福医学院、帝国理工等）——本章"生成器提名、独立判据裁决"分工的公开案例。来源：Google Research 官方博客与论文 arXiv:2502.18864。 FunSearch：自动验证器裁决下的数学新发现。DeepMind 的 FunSearch 用 LLM 提程序候选、确定性评估器打分、进化搜索迭代，在 cap set 问题上给出超越人类已知的新构造、并改进装箱问题启发式，成果发表于《自然》——本章四件套（生成器/验证器/进化库/闸门）的教科书级实现。来源：Nature 论文与 arXiv:2312.12439。 21.5 深度讲解 21.5.1 探索-利用权衡在 agent 中的三形态 教科书里的探索-利用是单臂老虎机：试新老虎机还是玩已知最好的那台。agent 系统里它以三种形态出现，各有各的预算账本。工具/策略形态：有 N 种已知策略（检索方式、提示词模板、模型档位），用哪种？这是经典多臂老虎机，UCB/Thompson 直接适用，回报是任务成功率，预算是调用次数。路径形态（解空间的搜索）：问题只有一个，解法空间是开放的（代码怎么写、计划怎么排）——这是进化搜索/爬山法的领地，预算花在变异与验证上，"利用"表现为围绕当前最优做局部变异，"探索"表现为偶尔的大幅改动或重启，防早熟收敛。知识形态（信息获取）：哪些查询值得发、哪些来源值得读——这是主动学习式的探索，回报是"信息增益"（这次查询消除了多少不确定性），预算是调用与时间成本；Burr Settles 综述里的核心结论在此适用：不确定性高的查询信息增益大，但代价与噪声也大，最优策略永远在"问最不确定的"与"问最有用的"之间。 三形态共用的度量是遗憾值（regret）：探索花掉的预算与"如果一开始就知道最优解"的收益之差。工程含义是：探索预算应与时间视野成正比——一次性的任务不值得探索（直接用先验最优），长期运行的系统值得持续投入固定比例的探索预算（比例换算成 UCB 的置信界宽度或 ε-greedy 的 ε）。常见的错误是把三种形态混在一个预算池里：策略探索（便宜、回报快）与路径搜索（昂贵、回报不确定）需要不同的账本与不同的停止条件。 regret 界值得一段直觉展开。Auer 等人证明 UCB1 的期望 regret 上界为 O(ln n)——准确说，n 轮之后每条次优臂被多拉的次数约为 8·ln n/Δ²（Δ 是它与最优臂的期望回报差，Auer et al. 2002, Machine Learning 47）。对数意味着探索的总成本有上界且增长极慢：哪怕跑一万轮，ln n 也不过 9 出头——每个「看似较差的假设」只需按这个量级复核几次，就能以高概率不错过真冠军。给探索预算的工程直觉因此是：长期运行的系统持续投入一小笔探索预算，在数学上是划算的；「探索会无限烧钱」的担忧没有理论依据。真正烧钱的是把预算花在 Δ 极小（两个假设难分伯仲）的对上——分母里的 Δ² 会让复核次数暴涨，此时该做的是加大重复次数把 Δ 估计准，而不是继续盲目加轮次。这也是 21.5.3 各层停止条件（硬上限、无改进早停、收益递减）背后的统一逻辑：探索的价值随置信度以对数速度衰减。 21.5.2 假设-实验-证伪循环：可证伪性作为设计要求 Popper 的划界标准给了探索循环一条铁律：一个假设必须携带"什么结果算它失败"的承诺，否则不配进入实验预算。工程化为假设的三要素：可执行预言（"按价值密度排序能把加权完成数提高 10% 以上"——可计算）、判定判据（在固定评测集上，差额经 N 次重复后仍显著）、失败处置（未达标则回滚并记录）。缺任何一环的假设都是不可证伪的空话——"这个策略可能更优""值得再试试"，验证器无从下手，循环会空转。 可证伪性在 LLM 探索循环里还有一个特殊敌人：生成器的自我辩护。模型提出假设后，如果你把验证的差结果喂回同一个模型问"这个假设还成立吗"，它会流畅地为失败辩护并修改预言（"我的意思是换个数据集后成立"）——预注册原则（先锁定判据与数据集，再出结果）是对策，与临床试验防 p-hacking 的机制完全相同。另一个工程化要点是预言的最小化：要求假设附带尽量窄的适用声明（"在处理时长小于 5 分钟的工单上有效"），窄预言被证伪时能精确定位边界，宽预言的失败则浪费整轮探索。 sequenceDiagram participant G as 假设生成器 participant V as 验证器 participant K as 进化库 G->>V: 候选 H7（附可执行预言与判据） V-->>G: 证伪：训练集提升仅 2%，未达显著 Note over K: 失败记录入库，沉淀为先验 G->>V: 变异 H8（冠军母本 + H7 失败先验） V-->>K: 通过：留出集复验达标 K-->>G: 冠军更新，证据包入库 Note over G: 下一轮以新冠军为母本继续变异 图 21-3：假设-证伪-变异-入库的交互时序——生成与验证隔离、判据预注册，证伪不是浪费而是先验；只有通过留出集复验的候选才配更新冠军并入库。 21.5.3 搜索预算管理：何时停止探索 停止条件是探索系统最容易漏配的部件——没有它的探索循环只有两种结局：预算烧穿，或者永远在等"下一个更好的解"。实用的停止条件组合有五层。硬上限：总迭代数、总 token/金额、墙钟时间，任一触顶即停——这是保险丝，无条件执行。无改进早停：连续 k 轮（如 10 轮）没有候选超过当前冠军即停；k 的选取与变异成功率的历史分布有关，过小会错过需要多步组合才能到达的改进，过大浪费预算。收益递减检测：最近 m 个冠军的改进幅度呈下降趋势且低于阈值——进化搜索的常见曲线是前期陡升后期平台，平台期的边际改进通常不值得继续。理论参照：UCB 的 regret 界告诉我们探索预算的边际价值随已试次数以对数速度衰减——预算分配应随置信度提升而向利用倾斜。外部触发：环境变化（语料更新、模型升级）使旧冠军的可信度失效，探索重开一轮——停止条件不是一次性的，是随环境周期性重置的。 预算在"广度与深度"之间的分配是另一半管理：候选太单一会早熟收敛于局部最优，候选太发散则每个都浅尝辄止。进化计算的 MAP-Elites 类质量-多样性算法给了工程化的答案：保留多个"生态位"的最优解（比如按策略风格分桶），而不是只留全局冠军——多样性的母本池是大跳跃式改进的前提。LLM 变异的实践技巧与此一致：给生成器看冠军之外还要看若干"风格不同"的次优解，提示词里显式要求"提出与现有候选不同的方向"，否则模型会反复微调同一个局部。 21.5.4 发现的验证闸门：自动验证器与对抗审稿 探索系统的公信力全部押在验证闸门上，闸门按强度分四级。一级：可执行判据（单元测试、数学核验、模拟环境回放）——最硬，FunSearch/AlphaEvolve 的发现都停在这一级（一个矩阵乘法算法要么用 48 次乘法算对，要么不是）；工程要求是验证器与生成器完全隔离（生成器不可访问验证器内部状态或测试数据）。二级：留出集复验——训练评测集上选出的冠军必须在从未参与选择的留出集上复现优势；这一级防的是探索循环特有的过拟合形态：几百个候选里挑出来的最好解，很可能只是拟合了评测集的噪声（选择效应），不做留出复验的"发现"大半是幻觉。「假宝藏」的机制值得算一笔账，因为探索系统最大的风险不是找不到，而是找到噪声。设某个评测集上有 500 个候选、真实水平同为 60 分、分数带 ±5 的随机噪声——「500 选 1」挑出的冠军，其期望分数约在真实水平之上 2.6 个噪声标准差（独立高斯的期望最大值），看起来的 70+ 分「发现」真实水平可能仍是 60。评测集上选出的最优解，天然是对该评测集噪声的过拟合——这不是运气差，是选择效应的数学必然（顺序统计量的期望最大值随候选数增长）。留出集复验之所以是生死线，正因为它把「带噪声榜单上的第一名」与「真实能力领先」重新拆开；留出集也要够大——几十条的留出集自身噪声就可能盖过改进幅度，复验结论反而不可信，经验上留出集应与训练集同一量级。FunSearch 的结果之所以可信，恰恰因为判据是纯机械的数学核验，没有可拟合的噪声：它在 n=8 维把已知最大 cap set 从 496 点推到 512 点，并把渐近下界从 2022 年的 2.218^n 提到 2.2202^n（Nature 625, 468-475, 2024）——二十年来该问题最大的进展，每一步都可被任何人重跑验证。 三级：对抗审稿——用独立模型扮演苛刻审稿人攻击发现（找反例、质疑适用范围、检查是否平凡），The AI Scientist 的教训在此必须反转利用：它的自动审稿器与生成器同源且可被注入，正确的配置是审稿模型异源、审稿提示词与生成提示词隔离、审稿意见不回流生成上下文。四级：人类评审——对外宣称的发现（写进产品、写进论文）必须过人，人类检查的是自动验证器覆盖不到的东西：新颖性是否平凡、结论是否重要、有没有自欺。 闸门之外还有复现性的工程要求：每个接受的发现附带证据包——假设原文、验证器版本、评测集版本（第 19 章的三元组版本纪律）、随机种子、完整运行日志。发现是可复现的实验结论，不是模型的一段自信输出。反过来说，验证闸门也是探索系统的成本大头：验证成本应计入预算管理（21.5.3），验证器太贵的域（真实世界实验）需要便宜的代理验证器（模拟、小规模试验），并接受代理与现实之间的差距风险。 flowchart TD L1["一级：可执行判据单元测试/数学核验/模拟回放"] --> L2["二级：留出集复验防「几百选一」的选择效应"] L2 --> L3["三级：对抗审稿异源模型扮演苛刻审稿人"] L3 --> L4["四级：人类签核对外宣称的发现必须过人"] 图 21-2：验证闸门的四级强度阶梯——越靠后越接近"担保"，对外宣称的发现至少要走到第四级。 21.5.5 与学习适应（第 9 章）的配合及失效模式 探索与学习的分工可以一句话说清：探索负责制造"哪个更好"的数据，学习负责把数据固化成无需再探索的直觉。工程上的配合接口有三个。数据接口：探索循环的每次验证产出（上下文、候选、分数）按第 9 章的格式沉淀，优化器（提示词改写、few-shot 库增删、模型微调）定期消化。策略接口：学习产出的先验（哪类假设历史上成功率高）反哺探索的预算分配——成功率高的一类假设获得更多变异轮次。节奏接口：探索是主动的、批式的、昂贵的；学习是被动的、持续的、便宜的；生产系统的常见节奏是"夜间批式探索 + 日间学习更新 + 每周冠军晋升评审"，与第 19 章的评估节奏咬合。 失效模式清单。奖励黑客：候选学会了钻验证器的空子（生成恰好通过测试用例的硬编码代码）——对策是测试集保密与动态轮换（第 19 章防污染纪律在探索场景的翻版）。冠军腐化：环境变了，老冠军早已过时，但它的分数还在参考表上镇住新假设——对策是冠军定期复验。验证器漂移：验证器自身被"优化"（有人为了让某个候选通过而放宽判据）——验证器的变更走评审流程，与第 19 章的门禁纪律相同。自恋循环：生成器与验证器同源（同一模型既出题又判卷），分数系统性虚高——异源是底线。过度探索：把生产流量当实验场，用户为低质探索买单——探索必须在影子流量或旁路环境进行。何时可以不用：解空间已知且小（枚举即可）；验证成本高到与真实实验无异且系统跑不了真实实验（此时只做执行不做发现）；以及一次性任务（探索的固定成本摊不薄）。 21.5.6 怎么用：运用判断 适用信号：出现以下特征值得上探索循环——解空间巨大且无法枚举（提示词、策略、算法构造）；判据可自动执行且比生成便宜（测试、模拟、数学核验）；当前最优解已停滞多轮无改进；有可承受的预算空间（调用与时间都有硬上限余量）；发现失败可安全回滚。边界条件与禁区：验证成本与真实实验无异、或解空间可枚举时，这套机器不划算；评测集太小（几十条）时留出复验自身噪声盖过改进幅度，「复现」反而不可信；以及一次性任务——探索的固定成本摊不平。 与最近替代方案的对比： 维度 本章（假设-验证-进化+留出复验） 网格/随机搜索 人工迭代 候选质量 LLM 带先验，采样有方向 无先验盲采样 依赖个人经验 防假发现 留出集+异源审稿+人签核 无（榜单冠军常是噪声） 强但不可扩展 成本结构 大头在验证，可预算 全花在采样上 全花在人力上 可复现性 证据包（判据/种子/日志） 通常只有最优解 记录不完整 落地三步：第一步（本周）：把要优化的目标写成确定性验证函数（测试集打分），切出 30% 样本做留出集并封存——先有可信的尺子再谈探索。第二步（本月）：让 LLM 围绕当前冠军提变异候选（每轮携带失败案例上下文），训练分超冠军才更替，连续 10 轮无改进早停，失败类型分桶记账。第三步（本季度）：冠军晋升前过第二道闸——留出集复验加异源模型对抗审稿；对外宣称的发现附证据包（假设、判据版本、随机种子、完整日志）并经人类签核。 21.6 工程落地：核心源码与讲解 21.6.1 核心实现：最小发现循环（片段讲解） 主程序拆为四个片段（Python 3.10+）。按序拼接即完整可运行程序：发现目标是进化一个任务排序启发式 order(jobs)（与第 20 章 EDF 基线呼应），验证器是确定性的加权准时完成率评分——训练集做选择、留出集做复验，防过拟合。未配置 AGENT_LLM_API_KEY 时用内置候选池跑通全流程（池内故意含语法损坏与运行崩溃样本，演示验证闸门的错误路径）。四个片段均为模块级定义，各自通过语法检查；exec 执行生成代码仅为演示，生产必须换沙箱子进程。 片段 1/4：统一模型接入与确定性候选池（含坏样本） &quot;&quot;&quot;假设 -&gt; 自动验证 -&gt; 进化 的最小发现循环（框架无关实现）。 发现目标：进化任务排序启发式 order(jobs)，最大化加权准时完成数。 四个片段按序拼接即完整可运行程序；依赖 pip install openai（可选）。 &quot;&quot;&quot; from __future__ import annotations import ast import os import random from dataclasses import dataclass FENCE = chr(96) * 3 # 围栏标记用 chr(96) 构造，避免与本书文档冲突 INITIAL_SKELETON = 'def order(jobs):
